// Power Local LLM — MetaGPT vs Agnai vs RisuAI: What Each Open-Source AI Tool Is Actually For
// Slug: metagpt-agnai-risuai-explained
// Clarification piece, not a feature-by-feature comparison. MetaGPT (multi-agent
// software-development framework) gets confused with Agnai and RisuAI (AI
// roleplay/companion chat frontends) because all three are open-source GitHub
// projects that use the words "agent" or "AI character." This article states
// what each is for and not for, with only a light comparative touch on Agnai
// vs. RisuAI — the deep feature comparison lives in
// sillytavern-vs-agnai-vs-risuai-roleplay.ts, which this article links to
// rather than duplicating.
// All 9 languages (en/de/fr/ja/zh/es/pt/ar/ko) have full content.

