          '**Agnai** (Rollenspiel-/Begleiter-Chat-Plattform): selbst hostbarer KI-Charakter-Chat mit Unterstützung für Gruppenchats mit mehreren Charakteren gleichzeitig, verbunden mit lokalen oder Cloud-LLM-Backends.',
          '**RisuAI** (Rollenspiel-Chat-Client): verfügbar als Web-, Desktop- (via Tauri) und Mobile-Version, kompatibel mit dem Character-Card-Format und mit Unterstützung für Lorebooks/World-Info für dauerhaften Geschichtskontext.',
          'MetaGPT ist kein Chat-Begleiter und keine Rollenspiel-Software — es hat überhaupt keine Personen-Chat-Funktion.',
