    title: 'MetaGPT vs Agnai vs RisuAI : à quoi sert vraiment chaque outil d\'agent IA',
    seoTitle: 'MetaGPT vs Agnai vs RisuAI : à quoi ça sert',
    intro: "MetaGPT, Agnai et RisuAI apparaissent côte à côte sur les listes « agents IA open source » et « personnages IA » parce que ces trois projets sont open source et auto-hébergeables et emploient tous le mot « agent » quelque part dans leur présentation — mais ils résolvent des problèmes totalement différents. MetaGPT est un framework multi-agents qui attribue à des agents IA des rôles calqués sur ceux d'une société de développement — chef de produit, architecte, ingénieur, QA — pour transformer une exigence d'une ligne en documents de conception, code et tests. Agnai et RisuAI sont deux plateformes de chat de compagnon IA et de jeu de rôle, auto-hébergeables, où l'on crée des personnages IA et discute avec eux. Presque personne qui veut vraiment l'un de ces trois outils ne veut aussi les deux autres. Ce guide indique clairement à quoi chaque outil est destiné, à quoi il ne l'est pas, et donne un repère léger — pas une refonte complète — sur la façon dont Agnai et RisuAI se comparent l'un à l'autre pour les lecteurs venus ici spécifiquement pour cette décision entre interfaces de jeu de rôle.",
