    intro: 'MetaGPT, Agnai y RisuAI aparecen juntos en listas de "agentes de IA open source" y "personajes de IA" porque los tres son proyectos de GitHub open source y autoalojables que usan la palabra "agente" en algún punto de su presentación — pero resuelven problemas completamente distintos. MetaGPT es un framework multiagente que asigna a agentes de IA roles calcados de una empresa de software — Product Manager, Arquitecto, Ingeniero, QA — para convertir un requisito de una línea en documentos de diseño, código y pruebas. Agnai y RisuAI son dos plataformas de chat de compañero y roleplay con IA, autoalojables, donde creas personajes de IA y hablas con ellos. Casi nadie que realmente quiera una de estas tres herramientas quiere también las otras dos. Esta guía indica con claridad para qué está pensada cada herramienta, para qué no, y da una referencia breve — no una reconstrucción completa — de cómo se comparan Agnai y RisuAI entre sí, para quienes llegan buscando específicamente esa decisión entre interfaces de roleplay.',
