          '**RisuAI** (cliente de chat de roleplay): disponible como web, aplicación de escritorio (vía Tauri) y versión móvil, compatible con el formato de tarjetas de personaje y con soporte de lorebooks/world-info para mantener contexto narrativo persistente.',
