        note: 'Si buscaste uno de estos tres nombres porque apareció en un ranking de "mejores agentes de IA open source" u "herramientas de IA open source" junto a los otros dos, ese ranking los agrupó por palabra de moda, no por función. Lee la sección "para qué / para qué no" más abajo para la herramienta concreta que buscabas.',
