    intro: 'MetaGPT, Agnai e RisuAI aparecem lado a lado em listas de "agentes de IA open source" e "personagens de IA" porque os três são projetos de GitHub de código aberto e auto-hospedáveis que usam a palavra "agente" em algum ponto da sua apresentação — mas resolvem problemas completamente diferentes. O MetaGPT é um framework multiagente que atribui a agentes de IA papéis inspirados em uma empresa de software — Product Manager, Arquiteto, Engenheiro, QA — para transformar um requisito de uma linha em documentos de design, código e testes. Agnai e RisuAI são duas plataformas de chat de companhia e roleplay com IA, auto-hospedáveis, onde você cria personagens de IA e conversa com eles. Quase ninguém que realmente queira uma dessas três ferramentas também quer as outras duas. Este guia deixa claro para que cada ferramenta foi feita, para que não foi, e dá uma referência leve — não uma reconstrução completa — de como Agnai e RisuAI se comparam entre si, para quem chega aqui buscando especificamente essa decisão entre interfaces de roleplay.',
