        content: '**تُجمَع هذه الأدوات الثلاث معًا لأنها تشترك في سمات سطحية لا علاقة لها بما تفعله فعليًا: الثلاثة مفتوحة المصدر، الثلاثة قابلة للاستضافة الذاتية، الثلاثة تتصل بخادم LLM خارجي بدلًا من تضمين نموذج ثابت، والثلاثة تستخدم مفردات "وكيل" أو "شخصية ذكاء اصطناعي" في وصف مشروعها الخاص.** يمكن لمقال على شكل قائمة عن "مشاريع وكلاء الذكاء الاصطناعي مفتوحة المصدر" أو "أدوات شخصيات الذكاء الاصطناعي مفتوحة المصدر" أن يضم الثلاثة بشكل مشروع دون أن يوضح أبدًا أن واحدة تكتب الأكواد بينما الأخريان تطبيقا دردشة.',
